class Main {
    public static void main(String[] args) {
        int[] stock = {4, 0, 3};
        int idx = 1;
        int score = 0;
        try {
            score += 1;
            int each = 12 / stock[idx];
            score += each;
        }
        // 0으로 나눈 경우를 따로 잡는 catch를 이 자리에 넣으세요.
        catch (ArithmeticException e) {
            score += 10;
        }
        catch (RuntimeException e) {
            score += 100;
        } finally {
            score += 1000;
        }
        System.out.println(score);
    }
}

